// Pseudo: evaluateImp(A,B) returns Kleene(A,B)
function evaluateImp(A,B){ // A,B in {T,F,U}
  // ¬A ∨ B with Kleene ordering T>U>F
  const not = {T:'F', F:'T', U:'U'}[A];
  const order = { 'F':0, 'U':1, 'T':2 };
  // ⩒ is max by value order
  const values = [not, B];
  let best = 'F';
  for (const v of values) if (order[v] > order[best]) best = v;
  return best;
}
```

